type QueryValue = string | number | boolean | readonly string[] | null | undefined;
export function queryString(values: Record<string, QueryValue>): string {
  const query = new URLSearchParams();
  for (const [key, value] of Object.entries(values)) {
    if (value === undefined || value === null) continue;
    if (Array.isArray(value)) value.forEach(item => query.append(key, String(item)));
    else query.set(key, String(value));
  }
  return query.toString();
}
export async function getApi<T>(baseUrl: string, path: string, values: Record<string, QueryValue> = {}, signal?: AbortSignal): Promise<T> {
  const qs = queryString(values);
  const response = await fetch(new URL(path + (qs ? "?" + qs : ""), baseUrl), { headers: { Accept: "application/json" }, signal });
  const data = await response.json();
  if (!response.ok) throw { status: response.status, ...(data as ApiError).error };
  return data as T;
}
// API_BASE lay tu cau hinh moi truong FE.
const API_BASE = "http://localhost:11000";
export async function integrationExample(): Promise<void> {
  const categories = await getApi<ArticleCategoryPage>(API_BASE, "/api/v1/article-categories", { section: "fraud", isField: true, page: 1, pageSize: 6 });
  const category = categories.items[0];
  if (!category) return;
  const articles = await getApi<ArticlePage>(API_BASE, "/api/v1/articles", { categoryId: category.id, page: 1, pageSize: 12 });
  const first = articles.items[0];
  if (!first) return;
  const detail = await getApi<ArticleDetail>(API_BASE, "/api/v1/articles/by-path", { path: first.url });
  const imageSrc = detail.image ? new URL(detail.image.url, API_BASE).href : null;
  console.log(detail.title, imageSrc, detail.bodyHtml, detail.relatedArticles);
  // Loai tru ID dung query lap, van giu bo loc false.
  const more = await getApi<ArticlePage>(API_BASE, "/api/v1/articles", { section: "fraud", showOnHome: false, excludeIds: [detail.id], pageSize: 3 });
  console.log(more.items);
}

