/** Ảnh media có url và alt; toàn bộ object có thể null. Media dùng chung không bảo đảm là ảnh đại diện của bài. URL tương đối được nối với origin của API/Media khi FE chạy trên domain khác. */
export type ArticleImage = {
  /** URL media, thường bắt đầu /media/. Đây là địa chỉ ảnh, không phải base64 hoặc ID CMS. Với FE khác origin dùng new URL(image.url, API_BASE).href. */
  url: string;
  /** Nội dung thuộc tính alt dưới dạng chữ thuần: ưu tiên altText của media, trống thì dùng tên media. Dùng binding thuộc tính để framework tự escape. */
  alt: string;
} | null;

/** Nhãn bài viết. FE dùng type cho logic/lọc và text cho câu chữ hiển thị; không dùng text làm mã query. */
export type ArticleLabel = {
  /** none: không nhãn; official-warning: dựa trên cảnh báo của cơ quan; unverified: cần kiểm chứng/chưa có kết luận. Đây là giá trị hợp lệ của query label. */
  type: "none" | "official-warning" | "unverified";
  /** Nhãn tiếng Việt đã ghép tên cơ quan nếu có. null khi không có nhãn; FE ẩn nhãn khi null hoặc rỗng. */
  text: string | null;
};

/** Thông tin xuất xứ do biên tập viên nhập. Các giá trị độc lập, đều có thể null; không đồng nghĩa với cơ quan chủ quản website. */
export type ArticleSource = {
  /** Tên cơ quan/tổ chức nguồn, hoặc null. Query sourceAgency tìm một phần tên này, không phân biệt hoa thường/dấu tiếng Việt. */
  agency: string | null;
  /** Số/ký hiệu văn bản nguồn dạng chuỗi, hoặc null; giữ nguyên chữ, dấu gạch và số, không chuyển thành số nguyên. */
  documentNumber: string | null;
  /** Ngày ban hành văn bản nguồn dạng YYYY-MM-DD, hoặc null; khác updatedDate và lastReviewedDate. */
  documentDate: string | null;
};

/** Tình trạng rà soát tính theo ngày Asia/Ho_Chi_Minh. Chỉ quá hạn khi số ngày đã qua > maxAgeDays; bằng ngưỡng chưa quá hạn. Không có ngày rà soát: isOverdue=false, message=null, nhưng trạng thái là unreviewed. */
export type ArticleReview = {
  /** Ngày gần nhất được biên tập viên đánh dấu đã rà soát, dạng YYYY-MM-DD hoặc null. FE không lấy updatedDate thay cho ngày này. */
  lastReviewedDate: string | null;
  /** Ngưỡng số ngày từ cài đặt website đã xuất bản, trong 1–3650. Thiếu/không hợp lệ dùng 90; FE không cố định ngưỡng 90. */
  maxAgeDays: number;
  /** true khi có lastReviewedDate và đã qua hơn maxAgeDays. false cũng có thể do chưa từng rà soát; xem thêm lastReviewedDate. */
  isOverdue: boolean;
  /** Câu nhắc tiếng Việt khi quá hạn, hoặc null nếu chưa quá hạn/chưa có ngày rà soát. Là chữ thuần, dùng để hiển thị lưu ý. */
  message: string | null;
};

/** SEO của danh mục/bài/trang. title ưu tiên seoTitle rồi tên CMS; description ưu tiên seoDescription rồi mô tả/tóm tắt. Ảnh ưu tiên ogImage; danh mục fallback heroImage1, bài fallback ảnh đại diện rồi heroImage1, trang fallback ảnh hero của trang. */
export type ArticleSeo = {
  /** Tiêu đề SEO để FE đặt document title/meta; có thể khác title của bài/danh mục hoặc hero.title. */
  title: string;
  /** Mô tả SEO dưới dạng chữ thuần, có thể rỗng. Dùng binding thuộc tính khi tạo meta description. */
  description: string;
  /** Ảnh chia sẻ mạng xã hội với fallback theo ArticleSeo; có thể null. Không đồng nghĩa với image ảnh đại diện hoặc hero.image. */
  image: ArticleImage;
  /** Cờ SEO của bản đã xuất bản. FE dùng cho chính sách robots/SEO; không phải cờ chưa publish và không tự loại nội dung khỏi các API danh mục/bài viết, kể cả query search của hợp đồng này. */
  hideFromSearch: boolean;
};

/** Danh mục articleList công khai để dựng thẻ lĩnh vực, chuyên đề hoặc đầu trang danh mục. Danh mục rỗng vẫn được trả, trừ khi lọc hasArticles=true. ID/role của danh mục khác ID của trang cố định. */
export type ArticleCategory = {
  /** GUID của document articleList. Dùng làm categoryId khi lấy bài hoặc {id} khi lấy chi tiết danh mục; không phải ID trang Thủ đoạn/Chính sách và không phải ID bài viết. */
  id: string;
  /** Tên danh mục đã xuất bản, dùng cho nhãn thẻ hoặc tiêu đề trang danh mục. Chữ thuần, cần render bằng textContent hoặc cơ chế escape của framework. */
  title: string;
  /** Một đoạn cuối của đường dẫn do CMS tạo. Có thể thay đổi khi đổi tên/đường dẫn; dùng id làm khóa và dùng url để điều hướng. */
  slug: string;
  /** Đường dẫn tương đối từ gốc portal, ví dụ /thu-doan/mua-ban-dat-coc/ hoặc /chinh-sach/. Dùng cho router FE và tham số path; lấy nguyên giá trị trả về, không tự ghép từ title/slug. */
  url: string;
  /** Mô tả ngắn của danh mục dưới dạng chữ thuần; có thể là chuỗi rỗng. Không phải nội dung HTML của bài viết. */
  summary: string;
  /** true nếu danh mục được đánh dấu là lĩnh vực trong CMS. false không có nghĩa là danh mục bị ẩn; có thể là Cảnh báo, Chuyên đề, Chuỗi bài hoặc Chính sách. */
  isField: boolean;
  /** Nhãn biểu tượng lĩnh vực trong CMS, có thể null. Ví dụ Cuộc gọi, Mua bán, Việc làm, Đầu tư, Vay nợ, Hợp đồng. Đây là nhãn để FE ánh xạ sang biểu tượng; không phải URL ảnh và khác iconKey của mục đích/cách thức. */
  fieldIcon: string | null;
  /** Tên vai trò tiếng Việt hoặc null: Cảnh báo, Bài đọc theo chuyên đề, Chuỗi bài, Chính sách. Khi gửi bộ lọc phải dùng mã tương ứng warning, topic, series, policy; role=null tương ứng categoryRole=none. Không lấy chuỗi role tiếng Việt làm giá trị query. */
  role: string | null;
  /** Tổng bài đã xuất bản và được phép công khai trực tiếp trong danh mục. Không phụ thuộc search, showOnHome, page hay pageSize của yêu cầu hiện tại; có thể bằng 0. */
  articleCount: number;
  /** SEO của danh mục. Luôn có object kể cả danh mục chưa có bài; title/mô tả có fallback và image có thể null. Xem ArticleSeo. */
  seo: ArticleSeo;
  /** Cờ Hiển thị ra trang chủ của riêng danh mục trong bản đã xuất bản. Mặc định false với dữ liệu chưa đánh dấu; độc lập với isField và showOnHome của các bài con. FE gửi showOnHome=true khi muốn áp dụng cờ này. */
  showOnHome: boolean;
  /** Chữ gợi ý/cách gọi khác của danh mục, có thể rỗng. Được dùng khi search danh mục; FE có thể giữ để gợi ý, không phải mảng nhãn hoặc danh sách bài. */
  searchKeywords: string;
  /** true khi articleCount == 0. FE có thể hiển thị nhãn Đang biên soạn; danh mục vẫn là nội dung công khai và vẫn có url/SEO. */
  isInPreparation: boolean;
};

/** Dữ liệu thẻ bài gọn, cũng dùng trong relatedArticles. Không có bodyHtml hoặc object category; muốn đủ thông tin bài dùng ArticleListItem/ArticleDetail. */
export type ArticleCard = {
  /** GUID của document article. Dùng gọi /articles/{id}, làm khóa danh sách hoặc đưa vào excludeIds của API bài viết; khác category.id và page.id. */
  id: string;
  /** Tên bài viết/văn bản đã xuất bản, dưới dạng chữ thuần. Không chứa markup để FE render như HTML. */
  title: string;
  /** Đoạn cuối đường dẫn bài do CMS tạo; có thể thay đổi. Dùng id làm khóa và url làm đường dẫn. */
  slug: string;
  /** Đường dẫn công khai của bài trên portal, đã gồm danh mục. Dùng router FE hoặc truyền nguyên giá trị vào path của /articles/by-path; không phải URL gọi API. */
  url: string;
  /** Tóm tắt dưới dạng chữ thuần; có thể rỗng. Dùng cho thẻ, danh sách hoặc phần mở đầu bài. */
  summary: string;
  /** Ảnh đại diện của riêng bài, gồm url/alt; null khi chưa gán hoặc chưa lấy được ảnh. Không tự lấy ảnh SEO làm ảnh đại diện. FE xử lý trạng thái không ảnh. */
  image: ArticleImage;
  /** Object nhãn luôn có. type là mã dùng cho bộ lọc; text là câu chữ tiếng Việt để hiển thị. type=none thường đi kèm text=null. */
  label: ArticleLabel;
  /** Thông tin nguồn của bài luôn có object, nhưng từng trường có thể null. Không suy ra nguồn cơ quan từ tên danh mục. */
  source: ArticleSource;
  /** Ngày cập nhật biên tập dạng YYYY-MM-DD, hoặc null. Không phải thời điểm máy chủ trả response; không tự chuyển múi giờ. Khi sắp theo ngày, ngày trống luôn cuối. */
  updatedDate: string | null;
  /** Cờ Bản dự thảo của văn bản/bài đã xuất bản. true vẫn có thể xuất hiện công khai. Không phải trạng thái chưa publish của CMS; API này không cung cấp bản nháp CMS. */
  isDraft: boolean;
  /** Kết quả rà soát tại ngày hiện tại ở Việt Nam. Luôn có object; lastReviewedDate có thể null. Dùng isOverdue/message để hiện lưu ý. */
  review: ArticleReview;
  /** Cờ Hiển thị ra trang chủ của riêng bài đã xuất bản. Không kế thừa cờ của danh mục. API chỉ lọc theo cờ khi FE gửi showOnHome=true/false. */
  showOnHome: boolean;
};

/** Đối tượng phân trang bài viết. Bộ lọc kết hợp AND, sau đó đếm, sắp xếp và phân trang. Không có kết quả là 200 với items=[]; categoryId hợp lệ nhưng không tồn tại/không công khai là 404. */
export type ArticlePage = {
  /** Object danh mục được chỉ định bởi categoryId, kể cả items=[]; null khi không gửi categoryId. Các phần tử items vẫn có category riêng. */
  category: NullableArticleCategory;
  /** Mảng kết quả của trang hiện tại; luôn là mảng, có thể [], không null. Đọc danh sách từ response.items. */
  items: Array<ArticleListItem>;
  /** Tổng số kết quả sau mọi bộ lọc và excludeIds, trước phân trang; không phải số phần tử của riêng trang hiện tại. */
  total: number;
  /** Trang được yêu cầu, bắt đầu từ 1. Không tự đưa về trang cuối khi vượt totalPages. */
  page: number;
  /** Số phần tử tối đa mỗi trang, trong 1–50; mặc định 12. Số items thực tế có thể nhỏ hơn. */
  pageSize: number;
  /** ceil(total / pageSize). Bằng 0 khi total=0; FE ẩn phân trang khi 0 hoặc 1. */
  totalPages: number;
};

/** Lỗi JSON dùng cho HTTP 400/404/503 của các endpoint trong hợp đồng. FE phân nhánh bằng error.code, dùng message/fields để hiển thị, không so sánh nội dung câu chữ. */
export type ApiError = {
  /** error.code là mã ổn định; câu chữ tiếng Việt có thể thay đổi. fields luôn có, nhưng có thể null. */
  error: {
  /** VALIDATION với HTTP 400: sai kiểu/giá trị đầu vào; NOT_FOUND với HTTP 404: không tìm thấy nội dung công khai trong phạm vi API. */
  code: "VALIDATION" | "NOT_FOUND" | "SEARCH_UNAVAILABLE";
  /** Thông báo tổng quát bằng tiếng Việt để FE hiển thị dạng chữ thuần; không chứa cấu trúc HTML. */
  message: string;
  /** Map tên query parameter → một thông báo lỗi tiếng Việt, ví dụ pageSize hoặc showOnHome. Thường có map ở 400; null ở 404 hoặc 503. FE đọc fields ?? {} và hiển thị gần bộ lọc tương ứng. */
  fields: Record<string, string> | null;
};
};

/** Chi tiết đầy đủ của một bài/văn bản đã xuất bản. Body có thể rỗng, đặc biệt với các văn bản chính sách đang chờ bổ sung. Không tạo bản nháp CMS từ API này. */
export type ArticleDetail = {
  /** GUID của document article. Dùng gọi /articles/{id}, làm khóa danh sách hoặc đưa vào excludeIds của API bài viết; khác category.id và page.id. */
  id: string;
  /** Tên bài viết/văn bản đã xuất bản, dưới dạng chữ thuần. Không chứa markup để FE render như HTML. */
  title: string;
  /** Đoạn cuối đường dẫn bài do CMS tạo; có thể thay đổi. Dùng id làm khóa và url làm đường dẫn. */
  slug: string;
  /** Đường dẫn công khai của bài trên portal, đã gồm danh mục. Dùng router FE hoặc truyền nguyên giá trị vào path của /articles/by-path; không phải URL gọi API. */
  url: string;
  /** Tóm tắt dưới dạng chữ thuần; có thể rỗng. Dùng cho thẻ, danh sách hoặc phần mở đầu bài. */
  summary: string;
  /** Ảnh đại diện của riêng bài, gồm url/alt; null khi chưa gán hoặc chưa lấy được ảnh. Không tự lấy ảnh SEO làm ảnh đại diện. FE xử lý trạng thái không ảnh. */
  image: ArticleImage;
  /** Object nhãn luôn có. type là mã dùng cho bộ lọc; text là câu chữ tiếng Việt để hiển thị. type=none thường đi kèm text=null. */
  label: ArticleLabel;
  /** Thông tin nguồn của bài luôn có object, nhưng từng trường có thể null. Không suy ra nguồn cơ quan từ tên danh mục. */
  source: ArticleSource;
  /** Ngày cập nhật biên tập dạng YYYY-MM-DD, hoặc null. Không phải thời điểm máy chủ trả response; không tự chuyển múi giờ. Khi sắp theo ngày, ngày trống luôn cuối. */
  updatedDate: string | null;
  /** Cờ Bản dự thảo của văn bản/bài đã xuất bản. true vẫn có thể xuất hiện công khai. Không phải trạng thái chưa publish của CMS; API này không cung cấp bản nháp CMS. */
  isDraft: boolean;
  /** Kết quả rà soát tại ngày hiện tại ở Việt Nam. Luôn có object; lastReviewedDate có thể null. Dùng isOverdue/message để hiện lưu ý. */
  review: ArticleReview;
  /** Danh mục chứa bài và SEO của danh mục; dùng category.url để dựng liên kết quay lại danh mục. */
  category: ArticleCategory;
  /** Nội dung HTML đã làm sạch ở máy chủ; có thể là chuỗi rỗng. Cho phép đoạn văn, h2/h3, đậm/nghiêng, danh sách, liên kết, trích dẫn, bảng và ảnh/chú thích; loại script/iframe/sự kiện/CSS nguy hiểm. Liên kết HTTP(S) tuyệt đối hoặc // được thêm target=_blank và rel=noopener noreferrer. Đây là trường nội dung HTML; các chuỗi khác là chữ thuần. */
  bodyHtml: string;
  /** Chữ thuần cho hộp Hành động an toàn, hoặc null. Không phải URL, ID trang hoặc nội dung HTML. */
  safeAction: string | null;
  /** SEO của riêng bài, không phải SEO danh mục. Xem ArticleSeo để biết thứ tự fallback ảnh và tiêu đề. */
  seo: ArticleSeo;
  /** Mảng tối đa 3 ArticleCard mới nhất cùng danh mục, không gồm bài đang xem. Có thể []; không được chọn theo showOnHome. Muốn tự lọc bài cho khối khác, gọi /articles và gửi excludeIds. */
  relatedArticles: Array<ArticleCard>;
  /** Cờ Hiển thị ra trang chủ của riêng bài đã xuất bản. Không kế thừa cờ của danh mục. API chỉ lọc theo cờ khi FE gửi showOnHome=true/false. */
  showOnHome: boolean;
};

/** Một phần tử items của API /articles: toàn bộ ArticleCard và danh mục chứa bài. Không có bodyHtml; search vẫn tìm được nội dung bài ở máy chủ. */
export type ArticleListItem = {
  /** GUID của document article. Dùng gọi /articles/{id}, làm khóa danh sách hoặc đưa vào excludeIds của API bài viết; khác category.id và page.id. */
  id: string;
  /** Tên bài viết/văn bản đã xuất bản, dưới dạng chữ thuần. Không chứa markup để FE render như HTML. */
  title: string;
  /** Đoạn cuối đường dẫn bài do CMS tạo; có thể thay đổi. Dùng id làm khóa và url làm đường dẫn. */
  slug: string;
  /** Đường dẫn công khai của bài trên portal, đã gồm danh mục. Dùng router FE hoặc truyền nguyên giá trị vào path của /articles/by-path; không phải URL gọi API. */
  url: string;
  /** Tóm tắt dưới dạng chữ thuần; có thể rỗng. Dùng cho thẻ, danh sách hoặc phần mở đầu bài. */
  summary: string;
  /** Ảnh đại diện của riêng bài, gồm url/alt; null khi chưa gán hoặc chưa lấy được ảnh. Không tự lấy ảnh SEO làm ảnh đại diện. FE xử lý trạng thái không ảnh. */
  image: ArticleImage;
  /** Object nhãn luôn có. type là mã dùng cho bộ lọc; text là câu chữ tiếng Việt để hiển thị. type=none thường đi kèm text=null. */
  label: ArticleLabel;
  /** Thông tin nguồn của bài luôn có object, nhưng từng trường có thể null. Không suy ra nguồn cơ quan từ tên danh mục. */
  source: ArticleSource;
  /** Ngày cập nhật biên tập dạng YYYY-MM-DD, hoặc null. Không phải thời điểm máy chủ trả response; không tự chuyển múi giờ. Khi sắp theo ngày, ngày trống luôn cuối. */
  updatedDate: string | null;
  /** Cờ Bản dự thảo của văn bản/bài đã xuất bản. true vẫn có thể xuất hiện công khai. Không phải trạng thái chưa publish của CMS; API này không cung cấp bản nháp CMS. */
  isDraft: boolean;
  /** Kết quả rà soát tại ngày hiện tại ở Việt Nam. Luôn có object; lastReviewedDate có thể null. Dùng isOverdue/message để hiện lưu ý. */
  review: ArticleReview;
  /** Danh mục công khai chứa bài này. Dùng category.id cho filter categoryId; không lấy id của bài hoặc page.id. */
  category: ArticleCategory;
  /** Cờ Hiển thị ra trang chủ của riêng bài đã xuất bản. Không kế thừa cờ của danh mục. API chỉ lọc theo cờ khi FE gửi showOnHome=true/false. */
  showOnHome: boolean;
};

/** Cùng cấu trúc ArticleCategory nhưng cho phép toàn bộ object bằng null. ArticlePage.category có object khi gửi categoryId hợp lệ, kể cả items=[]; null khi không gửi categoryId, bao gồm khi chỉ lọc section=policy. */
export type NullableArticleCategory = {
  /** GUID của document articleList. Dùng làm categoryId khi lấy bài hoặc {id} khi lấy chi tiết danh mục; không phải ID trang Thủ đoạn/Chính sách và không phải ID bài viết. */
  id: string;
  /** Tên danh mục đã xuất bản, dùng cho nhãn thẻ hoặc tiêu đề trang danh mục. Chữ thuần, cần render bằng textContent hoặc cơ chế escape của framework. */
  title: string;
  /** Một đoạn cuối của đường dẫn do CMS tạo. Có thể thay đổi khi đổi tên/đường dẫn; dùng id làm khóa và dùng url để điều hướng. */
  slug: string;
  /** Đường dẫn tương đối từ gốc portal, ví dụ /thu-doan/mua-ban-dat-coc/ hoặc /chinh-sach/. Dùng cho router FE và tham số path; lấy nguyên giá trị trả về, không tự ghép từ title/slug. */
  url: string;
  /** Mô tả ngắn của danh mục dưới dạng chữ thuần; có thể là chuỗi rỗng. Không phải nội dung HTML của bài viết. */
  summary: string;
  /** true nếu danh mục được đánh dấu là lĩnh vực trong CMS. false không có nghĩa là danh mục bị ẩn; có thể là Cảnh báo, Chuyên đề, Chuỗi bài hoặc Chính sách. */
  isField: boolean;
  /** Nhãn biểu tượng lĩnh vực trong CMS, có thể null. Ví dụ Cuộc gọi, Mua bán, Việc làm, Đầu tư, Vay nợ, Hợp đồng. Đây là nhãn để FE ánh xạ sang biểu tượng; không phải URL ảnh và khác iconKey của mục đích/cách thức. */
  fieldIcon: string | null;
  /** Tên vai trò tiếng Việt hoặc null: Cảnh báo, Bài đọc theo chuyên đề, Chuỗi bài, Chính sách. Khi gửi bộ lọc phải dùng mã tương ứng warning, topic, series, policy; role=null tương ứng categoryRole=none. Không lấy chuỗi role tiếng Việt làm giá trị query. */
  role: string | null;
  /** Tổng bài đã xuất bản và được phép công khai trực tiếp trong danh mục. Không phụ thuộc search, showOnHome, page hay pageSize của yêu cầu hiện tại; có thể bằng 0. */
  articleCount: number;
  /** SEO của danh mục. Luôn có object kể cả danh mục chưa có bài; title/mô tả có fallback và image có thể null. Xem ArticleSeo. */
  seo: ArticleSeo;
  /** Cờ Hiển thị ra trang chủ của riêng danh mục trong bản đã xuất bản. Mặc định false với dữ liệu chưa đánh dấu; độc lập với isField và showOnHome của các bài con. FE gửi showOnHome=true khi muốn áp dụng cờ này. */
  showOnHome: boolean;
  /** Chữ gợi ý/cách gọi khác của danh mục, có thể rỗng. Được dùng khi search danh mục; FE có thể giữ để gợi ý, không phải mảng nhãn hoặc danh sách bài. */
  searchKeywords: string;
  /** true khi articleCount == 0. FE có thể hiển thị nhãn Đang biên soạn; danh mục vẫn là nội dung công khai và vẫn có url/SEO. */
  isInPreparation: boolean;
} | null;

/** Một mục trong breadcrumb, theo thứ tự từ trang chủ đến trang hiện tại. */
export type ArticleBreadcrumb = {
  /** Nhãn liên kết dưới dạng chữ thuần. */
  title: string;
  /** Đường dẫn portal tương đối từ gốc; FE dùng với router. Không phải endpoint API. */
  url: string;
};

/** Metadata của trang cố định đã xuất bản trong Quản lý trang. page.id là ID trang thuDoanPage/chinhSachPage, khác ID kho articleList; không truyền page.id vào categoryId. */
export type ArticleContentPage = {
  /** GUID của trang cố định dùng nhận diện trang; không phải khóa của danh mục bài viết. */
  id: string;
  /** Tên trang trong CMS dưới dạng chữ thuần; có thể khác hero.title và seo.title. */
  title: string;
  /** Đường dẫn trang trên portal, như /thu-doan/ hoặc /chinh-sach/. */
  url: string;
  /** SEO của trang cố định, đọc từ tab SEO của chính trang đó; không lấy từ tên kho nội dung. */
  seo: ArticleSeo;
  /** Mảng breadcrumb theo thứ tự hiển thị. Render theo mảng trả về; không dùng ID trang làm ID danh mục. */
  breadcrumbs: Array<ArticleBreadcrumb>;
};

/** Liên kết do biên tập viên chọn, hoặc null khi thiếu/không hợp lệ/nút CMS đích chưa công khai. Cho phép đường dẫn nội bộ, #neo, http, https, mailto, tel. */
export type ArticleContentLink = {
  /** Chữ của liên kết, có thể rỗng; FE quyết định nhãn dự phòng phù hợp. */
  title: string;
  /** Đích liên kết do CMS trả về: đường dẫn portal, #neo hoặc URL http(s)/mailto/tel. Không giả định mọi link đều là đường dẫn nội bộ. */
  url: string;
  /** _blank, _self hoặc null. Với _blank, FE gắn rel="noopener noreferrer"; null dùng cách mở mặc định. */
  target: "_blank" | "_self" | null;
} | null;

/** Câu chữ và ảnh hero của trang; không chứa thông tin layout. Ảnh lấy từ nội dung biên tập, thiếu thì fallback heroImage3 của website; toàn bộ image vẫn có thể null. */
export type ArticleHeroContent = {
  /** Dòng nhãn nhỏ phía trên tiêu đề hero; có thể rỗng. */
  eyebrow: string;
  /** Phần chính của tiêu đề hero; thiếu nội dung nhập thì dùng tên trang cố định. */
  title: string;
  /** Phần tiêu đề cần nhấn mạnh, hoặc null. FE quyết định cách trình bày, không coi đây là HTML. */
  highlightTitle: string | null;
  /** Mô tả hero dưới dạng chữ thuần, có thể rỗng. */
  description: string;
  /** Ảnh hero với url/alt, hoặc null. Tách biệt ảnh đại diện bài và ảnh SEO. */
  image: ArticleImage;
};

/** Chỉ chứa câu chữ của tiêu đề/mô tả một nhóm nội dung, không chứa danh sách danh mục hay bài viết. */
export type ArticleContentHeading = {
  /** Nhãn nhỏ của nhóm, như Theo lĩnh vực hoặc Xu hướng; có thể rỗng. */
  eyebrow: string;
  /** Phần chính của tiêu đề nhóm dưới dạng chữ thuần. */
  title: string;
  /** Phần nhấn mạnh của tiêu đề, hoặc null; FE quyết định cách trình bày. */
  highlightTitle: string | null;
  /** Mô tả ngắn của nhóm dưới dạng chữ thuần; có thể rỗng. */
  description: string;
};

/** Một mục đích/cách thức lừa đảo từ dữ liệu lặp trong CMS. Giữ thứ tự mảng; iconKey là mã để FE ánh xạ biểu tượng, không phải CSS hoặc URL ảnh. */
export type ArticleInformationItem = {
  /** GUID của phần tử Block List, chỉ dùng làm khóa khi render; không gọi /articles/{id} hoặc truyền vào categoryId. */
  id: string;
  /** Tiêu đề mục dưới dạng chữ thuần. */
  title: string;
  /** Phần giải thích mục dưới dạng chữ thuần; có thể rỗng. */
  description: string;
  /** Mã biểu tượng: authority (cơ quan), people (người quen), profit (lợi nhuận), lock (khóa), warning (cảnh báo), fee (phí), document (giấy tờ), hoặc null nếu chưa chọn/không nhận diện được. */
  iconKey: null | "authority" | "people" | "profit" | "lock" | "warning" | "fee" | "document";
  /** true khi mục cần nhấn mạnh ý cảnh giác. Là ý nghĩa nội dung; FE tự chọn kiểu hiển thị. */
  isWarning: boolean;
};

/** Nhóm Mục đích hoặc Cách thức, có tiêu đề, danh sách lặp và lưu ý. Dữ liệu ban đầu 4/7 mục nhưng biên tập viên được thêm/xóa/sắp xếp; FE không cố định số phần tử. */
export type ArticleInformationSection = {
  /** Tiêu đề và mô tả chung của nhóm. */
  heading: ArticleContentHeading;
  /** Các mục nội dung theo đúng thứ tự CMS; có thể [], không null. */
  items: Array<ArticleInformationItem>;
  /** Lưu ý cuối nhóm dưới dạng chữ thuần, hoặc null. */
  note: string | null;
  /** Liên kết bổ sung cho lưu ý, hoặc null; xử lý theo ArticleContentLink. */
  noteLink: ArticleContentLink;
};

/** Câu chữ của ô tìm kiếm Thủ đoạn. FE gọi /article-categories?section=fraud&isField=true&search=... để tìm lĩnh vực, hoặc /articles?section=fraud&search=... để tìm bài. */
export type ArticleSearchContent = {
  /** Nhãn hiển thị và nhãn truy cập của ô tìm kiếm. */
  label: string;
  /** Gợi ý nhập từ khóa, không phải từ khóa mặc định. */
  placeholder: string;
  /** Chữ của nút tìm kiếm. */
  submitLabel: string;
  /** Lưu ý quyền riêng tư do biên tập viên nhập, hiển thị dạng chữ. */
  privacyNote: string;
  /** Thông báo không tìm thấy nội dung; FE dùng khi kết quả phù hợp rỗng. */
  emptyMessage: string;
};

/** Câu chữ và liên kết dẫn sang nội dung tiếp theo; từng liên kết có thể null. */
export type ArticleNextContent = {
  /** Nhãn giới thiệu phần tiếp theo, có thể rỗng. */
  eyebrow: string;
  /** Tiêu đề phần điều hướng tiếp theo. */
  title: string;
  /** Mô tả phần tiếp theo dưới dạng chữ thuần. */
  description: string;
  /** Liên kết hành động chính hoặc null. */
  primaryLink: ArticleContentLink;
  /** Liên kết hành động phụ hoặc null, độc lập với primaryLink. */
  secondaryLink: ArticleContentLink;
};

/** Nội dung biên tập trang Thủ đoạn. Các trường categories/alerts chỉ là tiêu đề nhóm; danh sách thực tế lấy riêng qua API danh mục/bài viết để FE tự chọn filter, thứ tự và số lượng. */
export type FraudPageContent = {
  /** Metadata, SEO và breadcrumb của trang Thủ đoạn. */
  page: ArticleContentPage;
  /** Câu chữ và ảnh hero. */
  hero: ArticleHeroContent;
  /** Câu chữ của ô tìm kiếm; không phải kết quả tìm kiếm. */
  search: ArticleSearchContent;
  /** Nhóm Họ muốn lấy: heading/items/note/noteLink; danh sách lặp, không phải bài viết. */
  objectives: ArticleInformationSection;
  /** Nhóm Cách thức lừa đảo: heading/items/note/noteLink; danh sách lặp theo CMS. */
  methods: ArticleInformationSection;
  /** Chỉ tiêu đề/mô tả khối Theo lĩnh vực. Lấy thẻ bằng /article-categories?section=fraud&isField=true. */
  categories: ArticleContentHeading;
  /** Chỉ tiêu đề/mô tả khối cảnh báo. Lấy bài bằng /articles?section=fraud&categoryRole=warning. */
  alerts: ArticleContentHeading;
  /** Nhãn hành động đọc bài, như Đọc; là chữ thuần. */
  readingActionLabel: string;
  /** Nhãn cho danh mục isInPreparation=true, như Đang biên soạn. */
  emptyCategoryLabel: string;
  /** Đơn vị sau số lượng bài, như thủ đoạn; FE ghép với articleCount. */
  articleCountLabel: string;
  /** Câu chữ và liên kết điều hướng cuối trang. */
  next: ArticleNextContent;
};

/** Nội dung trang Chính sách và số liệu trên toàn kho chính sách công khai, không phụ thuộc phân trang/từ khóa của lần gọi API bài viết khác. */
export type PolicyPageContent = {
  /** Metadata/SEO/breadcrumb của trang Chính sách. page.id không phải ID danh mục articleList dù hai mục có thể cùng url /chinh-sach/. */
  page: ArticleContentPage;
  /** Câu chữ và ảnh hero của trang Chính sách. */
  hero: ArticleHeroContent;
  /** Thông báo đã thay {count} trong mẫu CMS bằng draftArticleCount. null khi không còn văn bản dự thảo hoặc chưa nhập mẫu thông báo; không trả nguyên token để FE tự thay. */
  draftNotice: string | null;
  /** Thông báo do CMS cung cấp để FE dùng khi chưa có văn bản. Trường luôn có dù hiện tại đã có văn bản. */
  emptyMessage: string;
  /** Tổng văn bản đã xuất bản CMS, bao gồm cả văn bản mang nhãn Bản dự thảo. Không có nghĩa tất cả văn bản đã được ban hành chính thức. */
  publishedArticleCount: number;
  /** Số văn bản công khai có isDraft=true, không vượt publishedArticleCount. Số không mang nhãn dự thảo = publishedArticleCount - draftArticleCount. */
  draftArticleCount: number;
};

/** Đối tượng phân trang danh mục từ phiên bản 3.0.0; thay cho mảng trực tiếp. total=0 thì items=[] và totalPages=0; trang vượt tổng vẫn giữ total/page và items=[]. */
export type ArticleCategoryPage = {
  /** Mảng kết quả của trang hiện tại; luôn là mảng, có thể [], không null. Đọc danh sách từ response.items. */
  items: Array<ArticleCategory>;
  /** Tổng số kết quả sau mọi bộ lọc và excludeIds, trước phân trang; không phải số phần tử của riêng trang hiện tại. */
  total: number;
  /** Trang được yêu cầu, bắt đầu từ 1. Không tự đưa về trang cuối khi vượt totalPages. */
  page: number;
  /** Số phần tử tối đa mỗi trang, trong 1–50; mặc định 12. Số items thực tế có thể nhỏ hơn. */
  pageSize: number;
  /** ceil(total / pageSize). Bằng 0 khi total=0; FE ẩn phân trang khi 0 hoặc 1. */
  totalPages: number;
};

export type ArticleCategoryQuery = {
  /** Nhóm kho nội dung. Dùng policy để lấy Chính sách và fraud để lấy Thủ đoạn, không phải nhớ ID danh mục. */
  section?: "fraud" | "policy";
  /** Vai trò danh mục: none (không có), warning (Cảnh báo), topic (Bài đọc theo chuyên đề), series (Chuỗi bài), policy (Chính sách). */
  categoryRole?: "none" | "warning" | "topic" | "series" | "policy";
  /** true: danh mục được đánh dấu lĩnh vực; false: không phải lĩnh vực; bỏ qua: cả hai. */
  isField?: boolean;
  /** true: có ít nhất một bài được phép công khai; false: chưa có bài công khai. Bỏ trống: cả hai. */
  hasArticles?: boolean;
  /** Lọc cờ trang chủ của danh mục đã xuất bản. Bỏ trống lấy cả hai trạng thái. Khác với showOnHome của bài viết. Bỏ tham số khác với false; truyền false để lấy các mục chưa đánh dấu. Giá trị query dùng true/false, không dùng 1/0/null. */
  showOnHome?: boolean;
  /** Tìm tên, mô tả và từ gợi ý của danh mục; có dấu/không dấu. Chuỗi nguyên văn sau trim, tối đa 200 ký tự. Bỏ trống không lọc. */
  search?: string;
  /** Số trang tính từ 1. Trang vượt tổng trả items=[]; không tự chuyển về trang cuối. */
  page?: number;
  /** Số danh mục mỗi trang/khối, từ 1 đến 50; mặc định 12. Ngoài khoảng trả 400. Thay cho limit. */
  pageSize?: number;
  /** cms-order: thứ tự CMS; title-asc/title-desc: tiêu đề tiếng Việt tăng/giảm; article-count-asc/article-count-desc: số bài công khai tăng/giảm. Trống dùng cms-order; mã sau trim phân biệt hoa thường. */
  sort?: "cms-order" | "title-asc" | "title-desc" | "article-count-asc" | "article-count-desc";
  /** Loại ID danh mục trước khi đếm và phân trang; tối đa 50 GUID khác rỗng. Lặp excludeIds cho từng ID, không nối bằng dấu phẩy. ID không tồn tại được bỏ qua. */
  excludeIds?: Array<string>;
};

export type ArticleQuery = {
  /** Khóa GUID của danh mục lấy từ GET /article-categories. Bỏ trường hoặc để trống để lấy tất cả; GUID rỗng toàn số 0 không hợp lệ. */
  categoryId?: string;
  /** Tìm full-text bằng Examine trong tiêu đề, tóm tắt và phần chữ của nội dung bài. Không phân biệt hoa/thường và dấu tiếng Việt: dat coc tìm được đặt cọc. Mọi từ phải khớp trong cùng một bài, có thể nằm ở các trường khác nhau; không yêu cầu đúng cụm liền nhau. Tối đa 200 ký tự UTF-16 sau trim. Bỏ trường/chuỗi trắng: không lọc tìm kiếm. Dấu câu được tách khỏi từ; * % dấu ngoặc, dấu nháy và toán tử Lucene không được thực thi như cú pháp truy vấn. Chuỗi chỉ có dấu câu trả 200 với items=[]. Tìm theo từ, không hỗ trợ tìm chuỗi con bên trong một từ. Bài hoặc danh mục hideFromSearch không xuất hiện khi có search. Kết hợp được với tất cả bộ lọc và phân trang. */
  search?: string;
  /** Lọc label.type. Chuỗi trắng: không lọc. Giá trị sau trim phân biệt hoa thường. */
  label?: "none" | "official-warning" | "unverified";
  /** Ngày bắt đầu theo updatedDate, dạng YYYY-MM-DD, gồm cả ngày này. Bài không có updatedDate bị loại khi lọc khoảng ngày. */
  updatedFrom?: string;
  /** Ngày kết thúc theo updatedDate, dạng YYYY-MM-DD, gồm cả ngày này. Phải từ updatedFrom trở đi nếu nhập cả hai. */
  updatedTo?: string;
  /** overdue: đã vượt ngưỡng rà soát; current: có ngày rà soát và chưa vượt ngưỡng, gồm đúng ngưỡng hoặc ngày tương lai; unreviewed: chưa có ngày rà soát. Bỏ trường/chuỗi trắng: không lọc. Dùng ngày Việt Nam và ngưỡng CMS hiện hành. */
  reviewStatus?: "overdue" | "current" | "unreviewed";
  /** Lọc cờ nhãn Bản dự thảo của chính sách: true/false. Bỏ trường: cả hai. Không cho phép xem bản nháp chưa xuất bản của CMS. */
  isDraft?: boolean;
  /** Số trang tính từ 1. */
  page?: number;
  /** Số bài mỗi trang, từ 1 đến 50; mặc định 12. Ngoài khoảng trả 400, không tự điều chỉnh. */
  pageSize?: number;
  /** updated-desc/updated-asc: ngày cập nhật mới/cũ trước, ngày trống luôn cuối. title-asc/title-desc: tiêu đề theo thứ tự tiếng Việt tăng/giảm, không phân biệt hoa thường. Trống dùng updated-desc; mã sau trim phân biệt hoa thường. */
  sort?: "updated-desc" | "updated-asc" | "title-asc" | "title-desc";
  /** true: chỉ bài bật “Hiển thị ra trang chủ”; false: chỉ bài tắt; bỏ qua: cả hai. Bật/tắt phải được xuất bản trong CMS mới có hiệu lực. Bỏ tham số khác với false; truyền false để lấy các mục chưa đánh dấu. Giá trị query dùng true/false, không dùng 1/0/null. */
  showOnHome?: boolean;
  /** Nhóm kho nội dung. Dùng policy để lấy Chính sách và fraud để lấy Thủ đoạn, không phải nhớ ID danh mục. */
  section?: "fraud" | "policy";
  /** Vai trò danh mục: none (không có), warning (Cảnh báo), topic (Bài đọc theo chuyên đề), series (Chuỗi bài), policy (Chính sách). */
  categoryRole?: "none" | "warning" | "topic" | "series" | "policy";
  /** true: bài trong danh mục được đánh dấu lĩnh vực; false: bài trong danh mục không phải lĩnh vực; bỏ qua: cả hai. */
  isField?: boolean;
  /** true: bài có ảnh đại diện lấy được; false: bài chưa có ảnh đại diện; bỏ qua: cả hai. */
  hasImage?: boolean;
  /** Tìm một phần tên cơ quan nguồn, không phân biệt hoa/thường và dấu tiếng Việt; tối đa 200 ký tự sau trim. */
  sourceAgency?: string;
  /** Các ID bài cần loại trừ trước khi tính total và phân trang. Lặp excludeIds cho từng ID; tối đa 50, không dùng Guid rỗng. ID không tồn tại được bỏ qua. */
  excludeIds?: Array<string>;
};
